<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Notification\Message\Application\Service\Visibility\MessageVisibilityService;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageReadGateway;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageFilter;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageCursor;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class MessageListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly MessageVisibilityService $visibility,
        private readonly MessageReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Message");
        $span = $this->startSpan("Check allow of list usecase for Message");
        try {
            $result = $this->dispatcher->dispatch(new MessageListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(MessageFilter $filter): int
    {
        $this->logDebug("Run list usecase for Message");
        $span = $this->startSpan("Run list usecase for Message");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Message');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(MessageFilter $filter, ?MessageCursor $cursor = null): MessageAttributesSlide
    {
        $this->logDebug("Run list usecase for Message");
        $span = $this->startSpan("Run list usecase for Message");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new MessageAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
